INSERT INTO public.official_competencies (id, taxonomy_version, area, number, official_text) VALUES ('ENEM-MATRIZ-V1:LC.C1','ENEM-MATRIZ-V1','LC',1,'Aplicar as tecnologias da comunicação e da informação na escola, no trabalho e em outros contextos relevantes para sua vida.') ON CONFLICT DO NOTHING;
