INSERT INTO public.official_objects (id, taxonomy_version, area, block, official_text) VALUES ('ENEM-MATRIZ-V1:OBJ001','ENEM-MATRIZ-V1','LC','Estudo do texto','Modos de organização da composição textual; atividades de produção escrita e de leitura de textos gerados nas diferentes esferas sociais — públicas e privadas.') ON CONFLICT DO NOTHING;
