INSERT INTO public.official_objects (id, taxonomy_version, area, block, official_text) VALUES ('ENEM-MATRIZ-V1:OBJ031','ENEM-MATRIZ-V1','CN','Biologia — Ecologia e ciências ambientais','Ecossistemas; fatores bióticos/abióticos; habitat/nicho; comunidades; populações; interações; ciclos biogeoquímicos; fluxo de energia; biogeografia; biomas; recursos; mudanças climáticas; efeito estufa; desmatamento; erosão; poluição; conservação; biodiversidade; tecnologias ambientais; saneamento; legislação.') ON CONFLICT DO NOTHING;
INSERT INTO public.official_objects (id, taxonomy_version, area, block, official_text) VALUES ('ENEM-MATRIZ-V1:OBJ032','ENEM-MATRIZ-V1','CN','Biologia — Origem e evolução da vida','Biologia como ciência; hipóteses sobre origem; teorias evolutivas; pré-darwinismo; Darwin; síntese; seleção artificial.') ON CONFLICT DO NOTHING;
INSERT INTO public.official_objects (id, taxonomy_version, area, block, official_text) VALUES ('ENEM-MATRIZ-V1:OBJ033','ENEM-MATRIZ-V1','CN','Biologia — Qualidade de vida das populações humanas','Pobreza e desenvolvimento; indicadores; doenças; primeiros socorros; ISTs; drogas; gravidez na adolescência; obesidade; violência; exercício físico; sustentabilidade; legislação e cidadania.') ON CONFLICT DO NOTHING;
INSERT INTO public.official_objects (id, taxonomy_version, area, block, official_text) VALUES ('ENEM-MATRIZ-V1:OBJ034','ENEM-MATRIZ-V1','CH','Diversidade cultural, conflitos e vida em sociedade','Cultura material/imaterial; conquista da América; escravidão e resistências; povos africanos e indígenas; movimentos culturais.') ON CONFLICT DO NOTHING;
INSERT INTO public.official_objects (id, taxonomy_version, area, block, official_text) VALUES ('ENEM-MATRIZ-V1:OBJ035','ENEM-MATRIZ-V1','CH','Organização social, movimentos, pensamento político e Estado','Cidadania e democracia; Estado e direitos; democracia; revoluções; formação territorial; regiões; reordenamento; independências; Brasil imperial; liberalismo; migrações; revoluções do século XX; geopolítica; guerras; Guerra Fria; totalitarismos; ditaduras; pós-Guerra Fria; direitos; constituições; políticas afirmativas; vida urbana.') ON CONFLICT DO NOTHING;
INSERT INTO public.official_objects (id, taxonomy_version, area, block, official_text) VALUES ('ENEM-MATRIZ-V1:OBJ036','ENEM-MATRIZ-V1','CH','Características e transformações das estruturas produtivas','Escravismo; feudalismo; capitalismo; socialismo; economia agroexportadora; Revolução Industrial; espaço urbano-industrial; fordismo; toyotismo; industrialização brasileira; urbanização; globalização; agricultura; agronegócio; agricultura familiar; campo-cidade.') ON CONFLICT DO NOTHING;
INSERT INTO public.official_objects (id, taxonomy_version, area, block, official_text) VALUES ('ENEM-MATRIZ-V1:OBJ037','ENEM-MATRIZ-V1','CH','Domínios naturais e relação ser humano-ambiente','Apropriação de recursos; impactos econômicos; minerais/energéticos; recursos hídricos; bacias; mudanças climáticas; ilhas de calor; efeito estufa; chuva ácida; ozônio; ordem ambiental internacional; políticas ambientais; conservação; sustentabilidade; estrutura da Terra; solo; relevo; clima; vegetação.') ON CONFLICT DO NOTHING;
INSERT INTO public.official_objects (id, taxonomy_version, area, block, official_text) VALUES ('ENEM-MATRIZ-V1:OBJ038','ENEM-MATRIZ-V1','CH','Representação espacial','Projeções cartográficas; leitura de mapas temáticos, físicos e políticos; tecnologias modernas aplicadas à cartografia.') ON CONFLICT DO NOTHING;
